<template><view><PageHeader title="搜索" back-button/><view class="search-row"><input v-model="keyword" placeholder="请输入关键字" confirm-type="search" @confirm="search"/><button @click="search">搜索</button></view><view v-if="!searched" class="suggestions"><text>推荐标签</text><view class="tags"><button v-for="t in config.site_tab" :key="t" @click="choose(t)">{{t}}</button></view><view v-if="history.length" class="history-title"><text>搜索历史</text><text @click="clearHistory">清除</text></view><view class="tags"><button v-for="t in history" :key="t" @click="choose(t)">{{t}}</button></view></view><PostGrid v-else :posts="posts"/><view v-if="searched" class="state" @click="more">{{loading?'搜索中…':error||(!posts.length?'没有找到相关作品':hasMore?'加载更多':'已经到底了')}}</view></view></template>
<script setup>
import {ref} from 'vue';import {onReachBottom} from '@dcloudio/uni-app';import {config,request,searchLocal} from '../../lib/content';import PageHeader from '../../components/PageHeader.vue';import PostGrid from '../../components/PostGrid.vue';const keyword=ref(''),searched=ref(false),posts=ref([]),history=ref(uni.getStorageSync('crowlook:search')||[]),loading=ref(false),error=ref(''),hasMore=ref(false);let page=1,term='',generation=0;
const choose=t=>{keyword.value=t;search()};const clearHistory=()=>{history.value=[];uni.removeStorageSync('crowlook:search')};async function search(){if(!keyword.value.trim())return;generation++;term=keyword.value.trim();page=1;searched.value=true;posts.value=[];hasMore.value=true;loading.value=false;history.value=[term,...history.value.filter(t=>t!==term)].slice(0,8);uni.setStorageSync('crowlook:search',history.value);await more()}
async function more(){if(loading.value||!hasMore.value)return;loading.value=true;error.value='';const current=generation;try{let d=await request('post/list.json',{s:term,paged:page},'search'+term+page);if(current!==generation)return;posts.value=[...posts.value,...d.posts];hasMore.value=page<d.total_pages;page++}catch(e){if(current===generation){if(page===1)posts.value=searchLocal(term);error.value=posts.value.length?'当前展示已缓存作品，点击重试':e.message}}finally{if(current===generation)loading.value=false}}
onReachBottom(more)
</script>
<style scoped>.search-row{margin:16rpx 40rpx 62rpx;display:flex;align-items:center;gap:30rpx}.search-row input{background:#f6f6f6;border-radius:7rpx;height:70rpx;padding:0 22rpx;font-size:26rpx;flex:1;min-width:0}.search-row button{width:78rpx;flex-shrink:0;margin:0;padding:0;background:transparent;font-size:28rpx;line-height:70rpx}.suggestions{padding:0 40rpx;font-size:26rpx;color:#777}.tags{display:flex;gap:20rpx;flex-wrap:wrap;margin:32rpx 0 45rpx}.tags button{background:#f6f6f6;border-radius:4rpx;font-size:22rpx;margin:0;line-height:50rpx;padding:0 25rpx;color:#777}.history-title{display:flex;justify-content:space-between}.state{color:#aaa;text-align:center;font-size:24rpx;padding:50rpx 30rpx}</style>
